# ---- find the game
find_game() {
  local roots=() libs=() r f p
  for r in "$HOME/.steam/steam" "$HOME/.steam/root" "$HOME/.local/share/Steam" "$HOME/.var/app/com.valvesoftware.Steam/.local/share/Steam" "$HOME/snap/steam/common/.local/share/Steam"; do
    [ -d "$r" ] && roots+=("$r")
  done
  for r in "${roots[@]}"; do
    libs+=("$r")
    f="$r/steamapps/libraryfolders.vdf"
    if [ -f "$f" ]; then
      while IFS= read -r p; do libs+=("$p"); done < <(grep -oP '"path"\s+"\K[^"]+' "$f" 2>/dev/null)
    fi
  done
  for p in /run/media/*/* /run/media/* /media/*/* /mnt/*; do [ -d "$p/steamapps" ] && libs+=("$p"); done
  for p in "${libs[@]}"; do
    if [ -f "$p/steamapps/common/Zombie Assault/zombieassault.exe" ]; then echo "$p/steamapps/common/Zombie Assault"; return; fi
  done
}
